setMarked(startX, startY, UP, 1, 1, true);
visited[startX][startY] = true;
ans = 1;

While queue not empty:
Node v = q.poll();
int lev = v.lev;
int far = v.far;
int x2 = v.x, y2 = v.y;

if (lev == n+1) continue;

if (far != t[lev]) {
    x2 += dx[v.dir];
    y2 += dy[v.dir];
    if (isMarked(x2, y2, v.dir, lev, far+1)) continue;
    setMarked(x2, y2, v.dir, lev, far+1, true);
    q.add(new Node(x2, y2, v.dir, lev, far+1));
} else {
    int[] dirs = rot(v.dir);
    int d1 = dirs[0], d2 = dirs[1];
    if (!isMarked(v.x, v.y, d1, lev+1, 0)) {
        setMarked(v.x, v.y, d1, lev+1, 0, true);
        q.add(new Node(v.x, v.y, d1, lev+1, 0));
    }
    if (!isMarked(v.x, v.y, d2, lev+1, 0)) {
        setMarked(v.x, v.y, d2, lev+1, 0, true);
        q.add(new Node(v.x, v.y, d2, lev+1, 0));
    }
}

